	minContribution: f32,
	foveationStrength: f32,
	foveationCenter: f32,
	viewMatrix: mat4x4f,
	viewProj: mat4x4f,
	focal: f32,
	viewportWidth: f32,
	viewportHeight: f32,
	nearClip: f32,
	farClip: f32,
	isOrtho: u32,
